package com.campuslostfound.service;
import com.campuslostfound.db.DatabaseManager; import com.campuslostfound.exception.ValidationException; import com.campuslostfound.model.Student; import java.sql.*; import java.util.*;
public class UserService {
 public int addStudent(String name,String email,String studentId)throws SQLException,ValidationException{if(name==null||name.isBlank())throw new ValidationException("Name is required.");if(email==null||!email.contains("@"))throw new ValidationException("Enter a valid email.");if(studentId==null||studentId.isBlank())throw new ValidationException("Student ID is required.");String q="INSERT INTO users(name,email,role,student_id) VALUES(?,?,?,?)";try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,name.trim());p.setString(2,email.trim());p.setString(3,"STUDENT");p.setString(4,studentId.trim());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getInt(1);}}throw new SQLException("Could not create user.");}
 public List<Student> getStudents()throws SQLException{List<Student> a=new ArrayList<>();try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,name,email,student_id FROM users WHERE role='STUDENT' ORDER BY id");ResultSet r=p.executeQuery()){while(r.next())a.add(new Student(r.getInt(1),r.getString(2),r.getString(3),r.getString(4)));}return a;}
 public boolean exists(int id)throws SQLException{try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement("SELECT 1 FROM users WHERE id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next();}}}
}
